'use strict';
(()=>{
const C=window.NativeCards,W=window.NativeContent,$=id=>document.getElementById(id),main=$('main');
let profile=null,socket=null,room=null,queued=false,connected=false,pending=false,savePending=false,replaced=false,closed=false,reconnectTimer,toastTimer;
const pages=['home','collection','deck','rules','journey','ritual','progress','online','account','history','shop'];
let loaner='owned',deckSlot='deck-1',waiting=null,featurePending=false,authBusy=false,accountSwitch=false,recoveryCode=null,lastPack=null,packRevealed=false,leaderboard=[],requestCounter=0,emotesMuted=false;
try{emotesMuted=localStorage.getItem('native-emotes-muted')==='yes';}catch{}
let page=pages.includes(location.hash.slice(1))?location.hash.slice(1):'home';
let draft=null,draftName='',playerName='',dirty=false,search='',faction='all',tier='all',cost='all',catalogPage=0,selection=null,detailId=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=(deck,id)=>deck.filter(c=>c===id).length;
const limit=c=>c.tier==='SS'?1:3;
function toast(text){if(!text)return;$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4200);}
function send(msg){if(authBusy){toast('กำลังจัดการบัญชี กรุณารอสักครู่');return false;}if(!connected||socket?.readyState!==WebSocket.OPEN){toast('ยังไม่เชื่อมต่อเซิร์ฟเวอร์ กรุณารอสักครู่');return false;}socket.send(JSON.stringify(msg));return true;}
function resetDraft(){draft=profile.deck.slice();draftName=profile.deckName;playerName=profile.name;dirty=false;deckSlot=profile.activeDeck||'deck-1';}
const owned=c=>profile?.owned?(profile.owned[c.id]||0):limit(c);
function artStyle(c){const f=C.factions[c.faction];return `--faction:${f.color};--art:url('assets/cards/${c.faction}.png');--ax:${c.art%5*25}%;--ay:${Math.floor(c.art/5)*100/3}%`;}
function card(c,{action='inspect',uid='',selected=false,unaffordable=false,decorative=false}={}){
  const tag=decorative?'div':'button',f=C.factions[c.faction];
  return `<${tag} class="playing-card${(profile?.progress?.cards?.[c.id]||0)>=50?' awakened':(profile?.progress?.cards?.[c.id]||0)>=20?' mastered':''}${selected?' selected':''}${unaffordable?' unaffordable':''}" style="${artStyle(c)}" ${decorative?'aria-hidden="true"':`data-${action}="${esc(uid||c.id)}" aria-label="${esc(c.name)} · อาคม ${c.cost} · โจมตี ${c.atk} · ชีวิต ${c.hp}"`}><span class="card-cost">${c.cost}</span><span class="card-tier" data-tier="${c.tier}">${c.tier}</span><div class="card-art"></div><b class="card-name">${c.name}</b><span class="card-type"><span>${f.icon} ${f.element}</span><span>ภูติ · ${String(c.number).padStart(3,'0')}</span></span><p class="card-effect">${c.text}</p><span class="card-stats"><span><small>ATK</small>${c.atk}</span><span class="hp"><small>HP</small>${c.hp}</span></span></${tag}>`;
}
function header(){
  $('player-label').textContent=(profile?.name||'ผู้ผูกวิญญาณ')+(W&&profile?.equipped?.title?' · '+W.titleName(profile.equipped.title):'');$('connection').textContent=connected?'● เชื่อมต่อแล้ว':replaced?'เปิดเกมในอีกแท็บ':'● กำลังเชื่อมต่อ';$('connection').className='online-light'+(connected?' connected':'');
  document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===page&&!room)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});document.body.classList.toggle('in-duel',!!room);const wallet=$('wallet-label');if(wallet)wallet.textContent=profile?.wallet?`◉ ${profile.wallet.coins} · ✦ ${profile.wallet.tickets} · ◇ ${profile.wallet.shards}`:'';
}
function deckDots(deck){const counts=Object.keys(C.factions).map(f=>[f,deck.filter(id=>C.byId[id].faction===f).length]);return `<div class="deck-dots" aria-label="สัดส่วนธาตุในเด็ค">${counts.filter(([,n])=>n).map(([f,n])=>`<span style="--faction:${C.factions[f].color};--count:${n}" title="${C.factions[f].element} ${n} ใบ"></span>`).join('')}</div>`;}
function welcome(){if(!W||profile.starterChosen!==false)return '';return `<section class="weekly-banner"><span class="eyebrow">WELCOME GIFT · CLAIM ONCE</span><h2>เลือกสหายอีกหนึ่งธาตุ ฟรี</h2><p>คุณมีเด็คไม้พร้อมเล่นแล้ว เลือกรับการ์ดครบสำรับอีกหนึ่งธาตุ ระบบเพิ่มช่องเด็คให้เมื่อยังมีที่ว่าง และเก็บเด็คเดิมไว้</p><div class="starter-bar">${Object.entries(C.factions).map(([id,f])=>`<button style="--faction:${f.color}" data-feature-type="starter" data-feature-id="${id}" ${id==='wood'||featurePending?'disabled':''}>${f.icon} รับเด็ค${f.element}${id==='wood'?' · มีแล้ว':''}</button>`).join('')}</div></section>`;}
function home(){
  const legendary=[C.byId.g017,C.byId.g020,C.byId.g018];
  return `${welcome()}<section class="hero"><div class="hero-copy"><div class="hero-chips"><span>ชุดที่ ๑ · ร้อยภูติ</span><span>100 การ์ดต้นฉบับ</span><span>CHIBI THAI FOLKLORE</span></div><h1>ผูกวิญญาณเป็นมิตร<br><em>ปลุกตำนานด้วยการ์ด</em></h1><p>ในคืนที่สองโลกมาบรรจบ เลือกภูติคู่ใจ จัดสำรับแห่งอาคม แล้วเขียนตำนานบทใหม่ด้วยฝีมือของคุณ</p><div class="button-row"><button class="primary" data-solo="wood" ${!connected?'disabled':''}>เริ่มประลองกับ AI →</button><button class="secondary" data-view="deck">จัดเด็คของฉัน</button></div><small class="hero-note">เด็คเริ่มต้นพร้อมเล่น · สะสมการ์ดจากการเล่น · ทดลองทุกธาตุด้วยเด็คยืม</small></div><div class="hero-fan">${legendary.map((c,i)=>card(c,{decorative:true}).replace('style="',`style="--x:${(i-1)*85}px;--r:${(i-1)*12}deg;`)).join('')}<span class="fan-caption">THE FIRST SPIRIT COLLECTION</span></div></section><div class="home-bottom"><div class="play-options"><article class="mode-card"><span class="mode-icon">☽</span><h3>ฝึกวิชาอาคม</h3><p>ประลองกับแม่หมอม่วง เลือกคู่ต่อสู้จาก 5 สำรับ เรียนรู้คอมโบในจังหวะของคุณ</p><button class="secondary" data-opponents>เลือกคู่ต่อสู้ AI</button></article><article class="mode-card"><span class="mode-icon">⚔</span><h3>ประลองผู้ผูกวิญญาณ</h3><p>จับคู่ผู้เล่นจริงแบบ 1 ต่อ 1 เทิร์นละ 90 วินาที ใช้เด็คที่คุณบันทึกไว้</p><button class="primary" data-pvp ${!connected?'disabled':''}>ค้นหาคู่ต่อสู้ →</button></article></div><aside class="deck-overview"><span class="eyebrow">YOUR GRIMOIRE</span><div class="deck-name">${esc(profile.deckName)}</div>${deckDots(profile.deck)}<p>40 ใบ · พร้อมอัญเชิญ · ผสมได้ทุกธาตุ</p><button class="secondary" data-view="deck">เปิดสมุดสำรับ ↗</button><div class="profile-stats"><span>การ์ดในคลัง<b>${Object.keys(profile.owned||C.byId).filter(id=>id!=='wisp').length} / 100</b></span><span>ประลอง<b>${profile.matches}</b></span><span>ชนะ<b>${profile.wins}</b></span></div></aside></div><div class="section-heading"><div><span class="eyebrow">CHOOSE YOUR SPIRIT</span><h2>ห้าธาตุ ห้าหนทางแห่งอาคม</h2><p>เลือกตระกูลเพื่อเปิดคลังการ์ด หรือผสมธาตุในเด็คเดียวกัน</p></div><span>ตระกูลละ 20 ใบ</span></div><div class="faction-grid">${Object.entries(C.factions).map(([id,f])=>`<button class="faction-tile" style="--faction:${f.color}" data-faction-library="${id}"><i>${f.icon}</i><b>${f.name} · ธาตุ${f.element}</b><small>${f.description}</small></button>`).join('')}</div>`;
}
function toolbar(){return `<div class="catalog-toolbar"><input id="card-search" type="search" aria-label="ค้นหาการ์ด" placeholder="ค้นหาชื่อ หรือความสามารถ…" value="${esc(search)}"><select id="faction-filter" aria-label="กรองธาตุ"><option value="all">ทุกธาตุ</option>${Object.entries(C.factions).map(([id,f])=>`<option value="${id}" ${faction===id?'selected':''}>${f.icon} ธาตุ${f.element}</option>`).join('')}</select><select id="tier-filter" aria-label="กรอง Tier">${['all','SS','S','A','B','C'].map(t=>`<option value="${t}" ${tier===t?'selected':''}>${t==='all'?'ทุก Tier':t}</option>`).join('')}</select><select id="cost-filter" aria-label="กรองต้นทุน">${['all','1','2','3','4','5','6','7','8'].map(n=>`<option value="${n}" ${cost===n?'selected':''}>${n==='all'?'ทุกต้นทุน':'อาคม '+n}</option>`).join('')}</select></div>`;}
function matches(){return C.cards.filter(c=>(faction==='all'||c.faction===faction)&&(tier==='all'||c.tier===tier)&&(cost==='all'||c.cost===Number(cost))&&(!search||(c.name+' '+c.text).toLowerCase().includes(search.toLowerCase().trim())));}
function grid(builder=false){const all=matches(),pages=Math.max(1,Math.ceil(all.length/20));catalogPage=Math.min(catalogPage,pages-1);const list=all.slice(catalogPage*20,catalogPage*20+20);return `<p class="catalog-count" role="status">พบ ${all.length} ชนิด · ${builder?'แตะ + เพื่อเพิ่มลงเด็ค':'แตะการ์ดเพื่ออ่านความสามารถ'}</p><div class="card-grid">${list.length?list.map(c=>{const n=count(draft,c.id);return `<article class="collection-entry">${card(c)}<div class="collection-actions"><span>${builder?'ในเด็ค '+n+' / '+limit(c):'มี '+owned(c)+' ใบ · '+c.tier}</span><button data-add="${c.id}" aria-label="เพิ่ม ${c.name} ลงเด็ค" ${n>=owned(c)||n>=limit(c)||draft.length>=40||savePending?'disabled':''}>+ เพิ่ม</button></div></article>`;}).join(''):'<div class="empty-state"><b>ยังไม่พบภูติที่ตามหา</b>ลองเปลี่ยนคำค้นหรือเลือกธาตุอื่น</div>'}</div><nav class="catalog-pagination" aria-label="หน้าคลังการ์ด"><button class="secondary" data-catalog-page="${catalogPage-1}" ${catalogPage===0?'disabled':''}>← ก่อนหน้า</button><span>หน้า ${catalogPage+1} / ${pages}</span><button class="secondary" data-catalog-page="${catalogPage+1}" ${catalogPage>=pages-1?'disabled':''}>ถัดไป →</button></nav>`;}
function deckPanel(){
  const ids=[...new Set(draft)].sort((a,b)=>C.byId[a].cost-C.byId[b].cost||a.localeCompare(b)),curve=Array.from({length:8},(_,i)=>draft.filter(id=>C.byId[id].cost===i+1).length),max=Math.max(1,...curve);
  return `<div class="saved-decks"><label>สำรับที่แก้ไข<select id="deck-slot">${(profile.decks||[{id:'deck-1',name:profile.deckName,cards:profile.deck}]).map(d=>`<option value="${d.id}" ${deckSlot===d.id?'selected':''}>${esc(d.name)}${profile.activeDeck===d.id?' · ใช้อยู่':''}</option>`).join('')}${deckSlot==='new'?'<option value="new" selected>สำรับใหม่</option>':''}</select></label><button class="secondary" id="new-deck" ${(profile.decks?.length||1)>=5||savePending?'disabled':''}>+ ช่องใหม่</button></div><div class="deck-counter ${draft.length===40?'complete':''}"><h2>สำรับของฉัน</h2><span class="deck-count">${draft.length}<small style="font-size:14px"> / 40</small></span></div><div class="deck-fields"><label>ชื่อนักเดินทาง<input id="player-name" maxlength="18" value="${esc(playerName)}" ${savePending?'disabled':''}></label><label>ชื่อสำรับ<input id="deck-name" maxlength="32" value="${esc(draftName)}" ${savePending?'disabled':''}></label></div><div class="curve" aria-label="การกระจายต้นทุนอาคม">${curve.map((n,i)=>`<span title="อาคม ${i+1}: ${n} ใบ"><i style="--height:${n/max*100}%"></i><small>${i+1}</small></span>`).join('')}</div><div class="deck-list">${ids.length?ids.map(id=>{const c=C.byId[id];return `<div class="deck-row"><div class="mini-art" style="${artStyle(c)}"></div><span class="row-cost">${c.cost}</span><button class="row-name" data-inspect="${id}" aria-label="ดู ${c.name}">${c.name}</button><span>×${count(draft,id)}</span><button data-remove="${id}" aria-label="นำ ${c.name} ออกจากเด็ค" ${savePending?'disabled':''}>−</button></div>`;}).join(''):'<p class="muted">เลือกภูติจากคลังมาเป็นเพื่อนร่วมทาง</p>'}</div><div class="deck-tools"><button data-clear-deck ${savePending?'disabled':''}>ล้างสำรับร่าง</button><button data-reset-deck ${savePending?'disabled':''}>คืนค่าที่บันทึก</button></div><button class="primary" id="save-deck" ${draft.length!==40||draft.some(id=>count(draft,id)>owned(C.byId[id]))||!connected||savePending?'disabled':''}>${savePending?'กำลังบันทึก…':dirty?'บันทึกสำรับ · มีการแก้ไข':'บันทึกสำรับ'}</button><p class="deck-validation" role="status">${draft.length===40?(draft.some(id=>count(draft,id)>owned(C.byId[id]))?'ยังมีการ์ดไม่ครบจำนวนที่ใช้ · เรียกภูติหรือสร้างเพิ่ม':'✓ ครบ 40 ใบ พร้อมใช้งาน'):draft.length<40?'เพิ่มอีก '+(40-draft.length)+' ใบเพื่อบันทึก':'จำนวนเกิน 40 ใบ'}<br>ทั่วไปซ้ำได้ 3 · SS ชื่อละ 1 ใบ</p><p class="deck-summary muted" style="font-size:10px;margin-top:12px">บันทึกด้วยบัญชี Guest ของเบราว์เซอร์นี้ ล้างคุกกี้แล้วจะเข้าสู่บัญชีใหม่</p>`;
}
function collection(builder){return `<div class="section-heading"><div><span class="eyebrow">${builder?'DECK WORKSHOP':'SPIRIT ARCHIVE'} · FIRST EDITION</span><h1 style="font-size:30px;margin:5px 0">${builder?'จัดสำรับแห่งอาคม':'ร้อยภูติ คืนปลุกวิญญาณ'}</h1><p>${builder?'เลือกเด็คเริ่มต้น หรือผสมภูติจากทั้งห้าธาตุ การเปลี่ยนแปลงจะใช้หลังจากกดบันทึก':'100 ภูติ · 5 ธาตุ · ดูจำนวนที่มี หรือสร้างใบที่ต้องการจากเศษวิญญาณ'}</p></div></div>${builder?`<div class="starter-bar" aria-label="ใช้เด็คเริ่มต้น">${Object.entries(C.factions).map(([id,f])=>`<button style="--faction:${f.color}" data-starter="${id}" ${savePending?'disabled':''}>${f.icon} เด็ค${f.element}</button>`).join('')}</div>`:''}<div class="${builder?'deck-layout':''}"><section class="deck-catalog">${toolbar()}<div id="catalog-results">${grid(builder)}</div></section>${builder?`<aside class="deck-panel" id="deck-panel">${deckPanel()}</aside>`:''}</div>`;}
function rules(){return `<div class="section-heading"><div><span class="eyebrow">THE SPIRIT BINDER'S HANDBOOK</span><h1 style="font-size:31px;margin:5px 0">เริ่มต้นผูกวิญญาณ</h1><p>อัญเชิญให้ถูกจังหวะ เก็บอาคมให้พอ และอ่านความสามารถก่อนลงมือ</p></div></div><div class="rule-grid">${[
['01','เตรียมสำรับ','เด็ค 40 ใบ ใส่ซ้ำได้ชื่อเดียวละ 3 ใบ ยกเว้น SS ชื่อละ 1 ใบ ผสมธาตุได้ ทุกการ์ดในคลังใช้งานได้ทันที'],
['02','เริ่มการประลอง','ผู้เล่นมีชีวิต 30 สุ่มผู้เริ่มก่อน แต่ละฝ่ายถือไพ่ 5 ใบ ผู้เล่นแรกไม่จั่วในเทิร์นแรก ฝ่ายที่มีชีวิตเหลือเป็นผู้ชนะ'],
['03','พลังอาคม','เริ่ม 1 เพิ่มความจุเมื่อเริ่มเทิร์นของคุณ ครั้งละ 1 สูงสุด 8 และเติมเต็มทุกเทิร์น ใช้ตามต้นทุนมุมซ้ายของการ์ด'],
['04','อัญเชิญภูติ','เลือกไพ่ในมือ แล้วกดอัญเชิญ หากมีเป้าหมาย เลือกภูติที่มีขอบฟ้า สนามวางได้ 5 ตัว ภูติใหม่รอหนึ่งเทิร์นก่อนโจมตี'],
['05','โจมตีและโต้กลับ','เลือกภูติฝ่ายเราที่มีขอบเขียว แล้วเลือกศัตรู ทั้งสองทำความเสียหายตามค่าโจมตีพร้อมกัน ชีวิตที่เสียคงอยู่ เมื่อไม่มีภูติศัตรูจึงโจมตีผู้เล่นโดยตรงได้'],
['06','จบเทิร์น','ก่อนกดจบเทิร์น ลองตรวจว่ามีภูติที่ยังโจมตีได้หรือไม่ เทิร์นละ 90 วินาที หมดเวลาแล้วระบบส่งเทิร์นให้คู่ต่อสู้โดยอัตโนมัติ']
].map(([n,t,p])=>`<article class="rule-card"><i>${n}</i><h3>${t}</h3><p>${p}</p></article>`).join('')}</div><div class="section-heading"><div><span class="eyebrow">KEYWORDS</span><h2>อ่านภาษาแห่งอาคม</h2></div></div><dl class="keyword-list">${[
['◇ โล่','ป้องกันความเสียหายครั้งถัดไป 2 หน่วย แล้วโล่หายไป การมอบซ้ำไม่สะสม'],['❄ ตรึง','โจมตีไม่ได้ในเทิร์นถัดไปของตัวนั้น ยังถูกโจมตีและโต้กลับได้'],['⊘ ผนึก','หยุดความสามารถของภูติจนจบเทิร์นถัดไป ยังใช้ค่าพลังโจมตีพื้นฐานได้'],['เข้าสนาม','ทำงานเมื่ออัญเชิญจากมือ การชุบชีวิตจะไม่ทำงานซ้ำ'],['ภูติจิ๋ว','ภูติโทเคน 1/1 นับพื้นที่สนามตามปกติ และหายไปเมื่อออกจากสนาม'],['สุสานและเด็คหมด','ภูติที่ถูกทำลายจะเข้าสุสาน มือเต็มที่ 10 ใบแล้วไพ่จั่วใหม่ลงสุสาน เด็คหมดจะเสียชีวิตจากความเหนื่อยล้าเพิ่มขึ้นทุกครั้งที่จั่ว']
].map(([t,p])=>`<div><dt>${t}</dt><dd>${p}</dd></div>`).join('')}</dl><article class="rule-card" style="margin-top:22px"><h3>เกมออนไลน์และการบันทึก</h3><p>PvP ต้องมีอีกคนเลือกค้นหาคู่ต่อสู้ ไม่มี AI เติมคิว ทดสอบสองคนด้วยคนละเบราว์เซอร์หรือหน้าต่างส่วนตัว การเชื่อมต่อหลุดมีเวลา 20 วินาทีให้กลับมา ก่อนยอมแพ้อัตโนมัติ บัญชี Guest จำด้วยคุกกี้ รุ่นนี้ยังไม่มีล็อกอินหรือกู้บัญชี<br>ตัวละครผสมความเชื่อไทยกับเรื่องแต่งสำหรับเกม ไม่มีความหมายว่าเป็นข้อมูลตำนานจริงทั้งหมด</p></article>`;}
function unit(u,side){const c=C.byId[u.card],targetable=selection?.type==='hand'&&(room.targets[selection.uid]||[]).includes(u.uid),selected=selection?.type==='unit'&&selection.uid===u.uid;
  return `<button class="unit${u.ready?' ready':''}${u.sleep?' sleeping':''}${selected?' selected':''}${targetable?' targetable':''}" data-unit="${u.uid}" style="${artStyle(c)}" aria-label="${c.name} ${side===room.you?'ฝ่ายเรา':'ศัตรู'} โจมตี ${u.power} ชีวิต ${u.hp}${u.ready?' พร้อมโจมตี':''}${targetable?' เลือกเป็นเป้าหมายได้':''}"><div class="unit-art"><span class="unit-state">${u.shield?'<i>◇ '+u.shield+'</i>':''}${u.frozen?'<i>❄</i>':''}${u.sealed?'<i>⊘</i>':''}${u.sleep?'<i>รอ</i>':''}</span></div><div class="unit-name">${c.name}</div><div class="unit-stats"><span>⚔ ${u.power}</span><span class="${u.hp<u.maxHp?'wounded':''}">♥ ${u.hp}</span></div></button>`;
}
function board(p,side){return `<div class="board-row" aria-label="สนาม${side===room.you?'ฝ่ายเรา':'คู่ต่อสู้'}">${Array.from({length:5},(_,i)=>p.board[i]?unit(p.board[i],side):'<div class="board-slot" aria-hidden="true">✧</div>').join('')}</div>`;}
function duelist(p,enemy=false){return `<div class="duelist${enemy?'':' bottom'}${enemy&&selection?.type==='unit'&&!p.board.length?' enemy-target':''}" ${enemy?'data-player-target':''}><div class="duelist-icon">${W?.cosmetics.find(c=>c.id===(enemy?room.cosmetics?.find(m=>m.side!==room.you)?.equipped?.avatar:profile.equipped?.avatar))?.icon||(enemy?'☽':'✧')}</div><div class="duelist-name">${esc(p.name)}<small>${enemy?'คู่ประลอง':'ผู้ผูกวิญญาณของคุณ'} · เด็ค ${p.deckCount} ใบ</small></div><div class="mana-gems" aria-label="อาคม ${p.mana} จาก ${p.maxMana}">${Array.from({length:p.maxMana},(_,i)=>`<i class="${i<p.mana?'full':''}"></i>`).join('')}<b>${p.mana}/${p.maxMana}</b></div><div class="duelist-life"><small>HP</small> ${p.hp}<small> /${p.maxHp||30}</small></div>${enemy&&selection?.type==='unit'&&!p.board.length?'<button class="grave-button" data-hit-player>โจมตีผู้เล่น</button>':''}</div>`;}
function duel(){
  const me=room.players[room.you],enemy=room.players[1-room.you],mine=room.active===room.you&&room.canAct!==false,finished=room.phase==='finished',handSelection=selection?.type==='hand'?me.hand.find(h=>h.uid===selection.uid):null,selectedCard=handSelection?C.byId[handSelection.card]:null,attacker=selection?.type==='unit'?me.board.find(u=>u.uid===selection.uid):null;
  const hint=finished?'การประลองสิ้นสุดแล้ว':!mine?'แม่หมอกำลังคิด หรือรอคู่ต่อสู้ลงมือ':selectedCard?(room.targets[selection.uid]?.length?'เลือกเป้าหมายขอบฟ้าบนสนาม หรือให้เกมเลือกเป้าหมายแรก':'พร้อมอัญเชิญลงสนาม'):attacker?'เลือกภูติศัตรูเพื่อโจมตี หากสนามว่าง แตะผู้เล่นศัตรู':'เลือกไพ่ในมือเพื่ออัญเชิญ หรือภูติขอบเขียวเพื่อโจมตี';
  const result=finished?`<section class="battle-result" aria-live="polite"><div class="result-symbol">${room.winner===room.you?'✦':room.winner==='draw'?'☯':'☽'}</div><span class="eyebrow">DUEL COMPLETE</span><h2>${room.winner===room.you?'สายสัมพันธ์ของคุณคว้าชัย':room.winner==='draw'?'สองวิญญาณเสมอกัน':'คืนนี้… ยังมีบทเรียนให้เรียนรู้'}</h2><p>จบการประลองใน ${room.turn} เทิร์น${room.reward?` · +${room.reward.loot.xp} EXP · +${room.reward.loot.coins} เหรียญ · ✦ ${room.reward.loot.tickets}`:''}</p>${room.reward?`<div class="result-metrics"><span>⚔ ความเสียหาย ${room.reward.metrics.damage||0}</span><span>♥ ฟื้นฟู ${room.reward.metrics.healing||0}</span><span>◇ ป้องกัน ${room.reward.metrics.blocked||0}</span>${room.reward.ratingDelta?`<span>อันดับ ${room.reward.ratingDelta>0?'+':''}${room.reward.ratingDelta}</span>`:''}</div>`:''}<div class="button-row"><button class="primary" data-rematch>ประลองอีกครั้ง</button><button class="secondary" data-dismiss>กลับหมู่บ้าน</button></div></section>`:'';
  return `${result}<div class="duel-topbar"><div class="duel-title"><span class="eyebrow">${room.mode==='coop'?'CO-OP · ร่วมปราบมหาภูติ':room.rated?'RANKED · ประลองจัดอันดับ':room.mode==='pvp'?'LIVE PVP · ONLINE DUEL':room.challenge?'CHALLENGE · '+esc(room.challenge):'SPIRIT TRAINING · SOLO DUEL'}</span><h1>ลานอาคมใต้แสงจันทร์</h1></div><button class="secondary" id="concede" ${finished||!connected?'disabled':''}>ยอมแพ้ / ออกจากเกม</button></div><div class="duel-shell"><div><section class="duel-field ${profile.equipped?.board!=='board-default'?'has-custom-board':''}" style="--board-color:${W?.cosmetics.find(c=>c.id===profile.equipped?.board)?.color||'#243b37'};--back-color:${W?.cosmetics.find(c=>c.id===room.cosmetics?.find(m=>m.side!==room.you)?.equipped?.back)?.color||'#bda071'}" aria-label="สนามประลอง">${duelist(enemy,true)}<div class="enemy-hand" aria-label="คู่ต่อสู้ถือไพ่ ${enemy.handCount} ใบ">${Array.from({length:enemy.handCount},()=>'<span class="card-back" aria-hidden="true"></span>').join('')}</div>${board(enemy,1-room.you)}<div class="battle-divider"><span class="turn-pill ${mine?'mine':''}">${finished?'จบการประลอง':mine?'เทิร์นของคุณ':'เทิร์นคู่ต่อสู้'}</span><span>รอบ ${room.turn}</span><span class="turn-clock" id="turn-clock">—</span></div>${board(me,room.you)}${duelist(me)}</section><div class="hand-label"><span>ไพ่ในมือ ${me.handCount} / 10 ใบ · แตะเพื่อเลือก</span><span>ภูติใหม่รอ 1 เทิร์น</span></div><div class="hand-row" aria-label="ไพ่ในมือของคุณ">${me.hand.length?me.hand.map(h=>card(C.byId[h.card],{action:'hand',uid:h.uid,selected:selection?.uid===h.uid,unaffordable:C.byId[h.card].cost>me.mana})).join(''):'<div class="no-hand">ไม่มีไพ่ในมือ · จั่วเพิ่มเมื่อเริ่มเทิร์นถัดไป</div>'}</div></div><aside class="duel-sidebar"><section class="turn-action"><span class="eyebrow">${finished?'JOURNEY COMPLETE':mine?'YOUR TURN':'OPPONENT TURN'}</span><h2>${room.mode==='coop'&&!mine&&room.active===room.you?'ตาของ '+esc(room.controllerName):selectedCard?selectedCard.name:attacker?C.byId[attacker.card].name:finished?'ประลองเสร็จแล้ว':mine?'วางแผนอาคม':'รอจังหวะของคุณ'}</h2><p role="status">${hint}</p>${selectedCard?`<button class="primary" id="summon-card" ${!mine||pending||!connected||selectedCard.cost>me.mana||me.board.length>=5||finished?'disabled':''}>อัญเชิญ · ${selectedCard.cost} อาคม</button><div class="selected-detail"><b>${C.factions[selectedCard.faction].icon} ${selectedCard.name}</b>${selectedCard.text}</div><button class="cancel-selection" data-inspect="${selectedCard.id}">ขยายการ์ด ↗</button>`:`<button class="primary" id="end-turn" ${!mine||pending||!connected||finished?'disabled':''}>${pending?'กำลังส่งคำสั่ง…':'จบเทิร์น →'}</button>`}${selection?'<button class="cancel-selection" id="cancel-selection">ยกเลิกการเลือก</button>':''}${me.revealed?`<div class="selected-detail"><b>นกฮูกเห็นไพ่ในมือศัตรู</b>${C.byId[me.revealed].name}</div>`:''}</section><details class="duel-log" open><summary>บันทึกการประลอง</summary><ol>${room.log.slice().reverse().map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><div class="emote-row">${(W?.emotes||[]).map(e=>`<button data-emote="${e.id}" title="${e.text}">${e.id==='hello'?'✧':e.id==='thanks'?'❀':e.id==='nice'?'✦':e.id==='think'?'☽':e.id==='oops'?'👻':'⚔'}</button>`).join('')}<button id="mute-emotes" aria-pressed="${emotesMuted}">${emotesMuted?'เปิดอีโมต':'ปิดอีโมต'}</button></div><div class="duel-tools"><button class="grave-button" data-grave="${room.you}">สุสานเรา ${me.grave.length}</button><button class="grave-button" data-grave="${1-room.you}">สุสานศัตรู ${enemy.grave.length}</button><button class="grave-button" data-duel-help>วิธีเล่น</button></div></aside></div>`;
}
function render(){
  header();if(!profile){main.innerHTML='<div class="load-screen"><span>✧</span><h1>กำลังเปิดสมุดวิญญาณ…</h1><p>เชื่อมต่อและเตรียมสำรับเริ่มต้นให้คุณ</p></div>';return;}
  const oldFocus=document.activeElement,focusId=['card-search','faction-filter','tier-filter','cost-filter','player-name','deck-name'].includes(oldFocus?.id)?oldFocus.id:null,position=focusId&&typeof oldFocus.selectionStart==='number'?oldFocus.selectionStart:null;
  main.innerHTML=(!connected?'<div class="connection-warning" role="status">'+(replaced?'เกมถูกเปิดในอีกแท็บ รีเฟรชหน้านี้เพื่อกลับมาเล่น':'กำลังเชื่อมต่อใหม่ คำสั่งเล่นและบันทึกจะพร้อมเมื่อเชื่อมต่อสำเร็จ')+'</div>':'')+(room?duel():waiting?waitingPage():queued?'<section class="queue-panel"><div class="queue-symbol">✧</div><span class="eyebrow">MATCHMAKING</span><h1>กำลังรอผู้ผูกวิญญาณอีกคน</h1><p>อีกคนเลือก PvP เพื่อเริ่มเกม ไม่มี AI เติมคิว<br>ทดลองสองคนด้วยคนละเบราว์เซอร์หรือหน้าต่างไม่ระบุตัวตน</p><button class="secondary" id="cancel-queue">ยกเลิกการค้นหา</button></section>':page==='home'?home():page==='rules'?rules():['collection','deck'].includes(page)?collection(page==='deck'):features(page));
  if(focusId){const input=$(focusId);input?.focus({preventScroll:true});if(position!==null&&input?.type!=='search'&&input?.setSelectionRange)input.setSelectionRange(position,position);}
}
function navigate(next){if(room){toast('จบการประลองหรือยอมแพ้ก่อนเปลี่ยนหน้า');return;}if(queued||waiting){toast('ยกเลิกการค้นหาหรือห้องก่อนเปลี่ยนหน้า');return;}page=next;catalogPage=0;location.hash=next;render();window.scrollTo({top:0,behavior:'instant'});}
function openDetail(id){const c=C.byId[id];if(!c)return;detailId=id;const f=C.factions[c.faction];$('card-detail').innerHTML=`<div class="detail-layout">${card(c,{decorative:true})}<div class="detail-copy"><span class="eyebrow">${f.icon} ธาตุ${f.element} · ${c.tier} · NO.${String(c.number).padStart(3,'0')}</span><h2 id="detail-title">${c.name}</h2><p>${c.text}</p><div class="detail-stats"><span>⚔ ${c.atk}</span><span>♥ ${c.hp}</span><span>✦ ${c.cost}</span></div><p class="muted">${c.id==='wisp'?'โทเคนที่เกิดจากความสามารถ':'ใส่ซ้ำในเด็คได้สูงสุด '+limit(c)+' ใบ'}<br>${f.name} · ${f.description}</p>${!room&&!queued&&c.id!=='wisp'?`<button class="primary" data-add="${id}" ${draft.length>=40||count(draft,id)>=Math.min(limit(c),owned(c))||savePending?'disabled':''}>เพิ่มลงเด็ค · ${count(draft,id)}/${limit(c)}</button>`:''}</div></div>`;if(!room&&c.id!=='wisp'&&W){const extra=document.createElement('div');extra.innerHTML=`<p class="muted">เป็นเจ้าของ ${owned(c)} / ${limit(c)} ใบ · สายสัมพันธ์ ${profile.progress?.cards?.[id]||0} ครั้ง</p>${(profile.progress?.cards?.[id]||0)>=5?`<p class="muted">บันทึกสายสัมพันธ์: ${c.name} คือสหายแห่ง${f.name} พลังของเจ้าจะปรากฏเมื่อใช้ร่วมกับภูติที่ไว้ใจกัน</p>`:''}${(profile.progress?.cards?.[id]||0)>=20?`<button class="text-button" data-feature-type="title" data-feature-id="card:${id}">ใช้ฉายาสหายภูติ</button>`:''}<button class="secondary" data-craft="${id}" ${owned(c)>=limit(c)||!profile.wallet||profile.wallet.shards<W.craft[c.tier]||featurePending?'disabled':''}>สร้างการ์ด · ${W.craft[c.tier]} เศษวิญญาณ</button>`;$('card-detail').append(extra);}if(!$('card-dialog').open)$('card-dialog').showModal();}
function opponentPicker(){detailId=null;$('card-detail').innerHTML=`<span class="eyebrow">CHOOSE YOUR OPPONENT</span><h2 id="detail-title" style="margin-top:15px">ฝึกวิชากับแม่หมอม่วง</h2><p class="muted">เลือกสำรับของคู่ต่อสู้ แล้วใช้เด็คที่คุณบันทึกไว้เข้าประลอง</p><div class="faction-grid" style="grid-template-columns:repeat(2,1fr)">${Object.entries(C.factions).map(([id,f])=>`<button class="faction-tile" data-solo="${id}" style="--faction:${f.color}"><i>${f.icon}</i><b>${f.name}</b><small>${f.description}</small></button>`).join('')}</div>`;$('card-dialog').showModal();}
function action(msg){if(pending||!room||room.canAct===false||room.phase!=='playing')return;if(send({...msg,revision:room.revision})){pending=true;selection=null;render();}}
function tx(type,id=null,extra={}){if(featurePending||savePending)return;const request=window.crypto?.randomUUID?.()||Date.now()+'-'+(++requestCounter);if(send({type,id,request,...extra})){featurePending=true;render();}}
function sectionTitle(kicker,title,text=''){return `<div class="section-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${text}</p></div></div>`;}
function taskButton(mode,id,label='เริ่มท้าทาย →',f='wood'){return `<button class="primary" data-challenge-mode="${mode}" data-challenge-id="${id}" data-challenge-faction="${f}" ${!connected||featurePending?'disabled':''}>${label}</button>`;}
function loanerSelect(){return `<label class="loaner-select">สำรับที่ใช้เล่น<select id="loaner-choice"><option value="owned" ${loaner==='owned'?'selected':''}>เด็คที่บันทึก · ${esc(profile.deckName)}</option>${Object.entries(C.factions).map(([id,f])=>`<option value="${id}" ${loaner===id?'selected':''}>เด็คยืมธาตุ${f.element} · ไม่ต้องมีการ์ด</option>`).join('')}<option value="low" ${loaner==='low'?'selected':''}>เด็คยืมวิชาพื้นฐาน · C/B</option></select></label>`;}
function journey(){return sectionTitle('SPIRIT JOURNEY','เส้นทางผู้ผูกวิญญาณ','ผ่านบทฝึก ไขปริศนา และรับตั๋วจากชัยชนะครั้งแรกของแต่ละด่าน')+loanerSelect()+`<div class="section-heading"><h2>เรียนรู้ด้วยการลงมือ</h2><span>${profile.progress.lessons.length}/3 บท</span></div><div class="feature-grid">${W.lessons.map(l=>`<article class="activity-card"><span class="eyebrow">TUTORIAL ${profile.progress.lessons.includes(l.id)?'· ✓ ผ่านแล้ว':''}</span><h3>${l.name}</h3><p>${l.text}</p><small>เป้าหมาย: ${l.goal} · ครั้งแรก ✦ 1 / EXP 40</small>${taskButton('lesson',l.id,'เริ่มบทฝึก →')}</article>`).join('')}</div><div class="section-heading"><h2>ปริศนาอาคม</h2><span>สนามและไพ่ที่กำหนด · ชนะในเทิร์นเดียว</span></div><div class="feature-grid">${W.puzzles.map(p=>`<article class="activity-card"><span class="eyebrow">PUZZLE ${profile.progress.puzzles.includes(p.id)?'· ✓ ผ่านแล้ว':''}</span><h3>${p.name}</h3><p>${p.text}</p><small>ครั้งแรก ✦ 1 / EXP 40</small>${taskButton('puzzle',p.id)}</article>`).join('')}</div><div class="section-heading"><h2>ตำนานห้าศาล</h2><span>${profile.progress.bosses.length}/5 ตำนาน</span></div><div class="feature-grid boss-grid">${W.bosses.map(b=>`<article class="activity-card"><div class="boss-art mini-art" style="${artStyle(C.byId[b.card])}"></div><span class="eyebrow">${C.factions[b.id].icon} ${profile.progress.bosses.includes(b.id)?'✓ พิชิตแล้ว':'BOSS CHALLENGE'}</span><h3>${b.name}</h3><p>${b.text}</p><small>บอส 36 HP · ครั้งแรก ✦ 1 / EXP 80</small>${taskButton('boss',b.id,'ท้าประลอง →',b.id)}</article>`).join('')}</div><article class="weekly-banner"><span class="eyebrow">WEEKLY ARCANA</span><h2>${W.weekly().name}</h2><p>${W.weekly().text} · ชนะครั้งแรกในสัปดาห์รับตั๋ว 2 ใบ และ EXP 80</p>${taskButton('weekly','event','เข้าสู่ลานประจำสัปดาห์ →')}</article>`;}
function ritual(){return sectionTitle('SPIRIT SUMMONING','พิธีเรียกภูติ','ตั๋วได้จากการเล่นและภารกิจ ไม่มีการเติมเงินจริง การ์ดซ้ำส่วนเกินเปลี่ยนเป็นเศษวิญญาณอัตโนมัติ')+`<div class="wallet-strip"><b>✦ ตั๋ว ${profile.wallet.tickets}</b><b>◇ เศษวิญญาณ ${profile.wallet.shards}</b><b>◉ เหรียญ ${profile.wallet.coins}</b></div><div class="pity-track"><div><span>S ขึ้นไปภายใน 10 ซอง</span><progress value="${profile.pity.s}" max="10"></progress><b>${profile.pity.s} / 10</b></div><div><span>SS ภายใน 40 ซอง</span><progress value="${profile.pity.ss}" max="40"></progress><b>${profile.pity.ss} / 40</b></div></div><div class="feature-grid pack-grid">${[['all',{name:'ร้อยภูติ',icon:'✧',color:'#ddc590'}],...Object.entries(C.factions)].map(([id,f])=>`<article class="pack-choice" style="--faction:${f.color}"><div class="summon-seal">${f.icon}</div><span class="eyebrow">5 CARDS · A+ GUARANTEED</span><h3>ซอง${f.name}</h3><p>${id==='all'?'รวมการ์ดจากทุกธาตุ':'การ์ดในซองเป็นธาตุ'+f.element+'ทั้งหมด'}</p><button class="primary" data-pack="${id}" ${profile.wallet.tickets<1||featurePending||!connected?'disabled':''}>${featurePending?'กำลังทำพิธี…':'เรียกภูติ · ✦ 1'}</button></article>`).join('')}</div><div class="button-row"><button class="secondary" data-feature-type="ticket" ${profile.wallet.coins<100||featurePending?'disabled':''}>แลก 100 เหรียญ → ตั๋ว 1 ใบ</button><button class="secondary" id="last-pack" ${!profile.lastPack?'disabled':''}>ดูซองล่าสุด</button><button class="secondary" data-view="collection">สร้างการ์ดเจาะจงในคลัง →</button></div><details class="rate-details"><summary>อัตราดรอป การันตี และเศษวิญญาณ</summary><p>ช่องสุ่มปกติแต่ละช่อง: C 50% · B 30% · A 15% · S 4% · SS 1% สุ่มใน Tier และธาตุที่เลือกอย่างเท่าเทียมกัน</p><p>หากทั้ง 5 ช่องไม่มี A ขึ้นไป ช่องสุดท้ายจะสุ่มใหม่เฉพาะ A 75% / S 20% / SS 5% การันตี 10 หรือ 40 ซองจะยกระดับช่องสุดท้ายเมื่อจำเป็น จึงทำให้อัตรารวมหลังการันตีสูงกว่าอัตราช่องปกติ ตัวนับใช้ร่วมทุกซอง S หรือ SS จะรีเซ็ตตัวนับ S และ SS จะรีเซ็ตทั้งคู่</p><table><thead><tr><th>Tier</th><th>ซ้ำเกินใช้ → เศษ</th><th>สร้าง 1 ใบ</th></tr></thead><tbody>${Object.keys(W.craft).map(t=>`<tr><td>${t}</td><td>${W.dust[t]}</td><td>${W.craft[t]}</td></tr>`).join('')}</tbody></table><p>เก็บการ์ดทั่วไปสูงสุด 3 ใบต่อชื่อ และ SS สูงสุด 1 ใบ ไม่ต้องย่อยการ์ดที่ใช้อยู่ การเปิดซองเพิ่มค่าพลังให้การ์ดเดิมไม่ได้</p></details>`;}
function progressPage(){const p=profile,pr=p.progress;return sectionTitle('GROW TOGETHER','ภารกิจและสายสัมพันธ์','ความคืบหน้าจากเกมจบตามปกติที่เล่นถึงเทิร์น 5 อัญเชิญอย่างน้อย 1 และโจมตีอย่างน้อย 1 · ห้องเพื่อนไม่ให้รางวัลสะสม')+`<div class="wallet-strip"><b>ระดับ ${1+Math.floor(p.xp/100)} · EXP ${p.xp}</b><span>ภารกิจรีเซ็ต 00:00 น. ประเทศไทย · รับผลเล่นสะสมได้ 20 เกมต่อวัน</span></div><div class="section-heading"><h2>ภารกิจประจำวัน</h2><span>เปลี่ยนได้วันละครั้ง</span></div><div class="feature-grid">${p.daily.quests.map(id=>{const q=W.quests.find(q=>q.id===id),n=p.daily.progress[q.key]||0,claimed=p.daily.claimed.includes(id);return `<article class="activity-card"><h3>${q.name}${p.daily.carry===id?' · ต่อจากเมื่อวาน':''}</h3><p>${q.text}</p><progress value="${Math.min(n,q.goal)}" max="${q.goal}"></progress><small>${n}/${q.goal} · ✦ ${q.tickets} / EXP ${q.xp} / ◉ ${q.coins}</small><button class="primary" data-feature-type="quest" data-feature-id="${id}" ${n<q.goal||claimed||featurePending?'disabled':''}>${claimed?'✓ รับแล้ว':'รับรางวัล'}</button><button class="text-button" data-feature-type="reroll" data-feature-id="${id}" ${p.daily.rerolled||claimed||featurePending?'disabled':''}>เปลี่ยนโจทย์นี้</button></article>`;}).join('')}</div><article class="weekly-banner"><h3>ผู้พิชิตศาลประจำสัปดาห์</h3><p>ชนะบอสใดก็ได้หนึ่งครั้งในสัปดาห์ · ตั๋ว 3 ใบ / EXP 120</p><button class="primary" data-feature-type="weekly-reward" ${!p.weekly.boss||p.weekly.claimed||featurePending?'disabled':''}>${p.weekly.claimed?'✓ รับแล้ว':'รับรางวัลประจำสัปดาห์'}</button></article><div class="section-heading"><h2>สมุดความสำเร็จ</h2></div><div class="feature-grid">${W.achievements.map(a=>{const claimed=pr.achievements.includes(a.id);return `<article class="activity-card"><h3>${a.name}</h3><p>${a.text}</p><small>ตั๋ว ${a.tickets} ใบ${a.cosmetic?' · หลังการ์ดพิเศษ':''}</small><button class="secondary" data-feature-type="achievement" data-feature-id="${a.id}" ${claimed||featurePending?'disabled':''}>${claimed?'✓ ปลดล็อกแล้ว':'ตรวจสอบและรับรางวัล'}</button>${claimed?`<button class="text-button" data-feature-type="title" data-feature-id="achievement:${a.id}">ใช้ฉายานี้</button>`:''}</article>`;}).join('')}</div><div class="section-heading"><h2>เส้นทางผู้ผูกวิญญาณ</h2><span>รางวัลฟรี 20 ระดับ · ไม่รีเซ็ต</span></div><div class="pass-track">${Array.from({length:20},(_,i)=>{const level=i+1,claimed=pr.pass.includes(level);return `<button data-feature-type="pass" data-feature-id="${level}" ${claimed||p.xp<level*100||featurePending?'disabled':''}><b>${level}</b><span>✦ ${level%5===0?2:1}</span><small>${claimed?'✓ รับแล้ว':level*100+' EXP'}</small></button>`;}).join('')}</div><div class="section-heading"><h2>ความชำนาญห้าธาตุ</h2><span>เล่นการ์ดสะสม · ไม่มีการเพิ่มค่าพลัง</span></div><div class="faction-grid">${Object.entries(C.factions).map(([id,f])=>{const n=pr.factions[id]||0;return `<article class="faction-tile" style="--faction:${f.color}"><i>${f.icon}</i><b>${f.name}</b><small>อัญเชิญ ${n} ครั้ง · ระดับ ${Math.min(5,Math.floor(n/25))}</small><progress value="${Math.min(n,125)}" max="125"></progress>${n>=25?`<button class="text-button" data-feature-type="title" data-feature-id="faction:${id}">ใช้ฉายาศิษย์ธาตุ${f.element}</button>`:''}</article>`;}).join('')}</div><p class="muted">สายสัมพันธ์ประจำการ์ดดูได้เมื่อเปิดรายละเอียด: 5 ครั้งเปิดบันทึก · 20 ครั้งกรอบทองและฉายา · 50 ครั้งประกายพิเศษ</p>`;}
function online(){const p=profile;return sectionTitle('PLAY WITH YOUR FRIENDS','ลานประลองออนไลน์','คิวสาธารณะร่วมกัน จับคู่ตามระดับฝีมือ และขยายช่วงเมื่อรอนาน ห้องเพื่อนใช้รหัสเข้าห้อง')+loanerSelect()+`<div class="feature-grid"><article class="activity-card"><span class="eyebrow">PUBLIC DUEL</span><h3>ประลองทั่วไป</h3><p>ใช้เด็คของคุณหรือเด็คยืม ทดลองคอมโบกับผู้เล่นจริงโดยไม่เสียคะแนนฤดูกาล</p><button class="primary" data-pvp ${!connected?'disabled':''}>ค้นหาคู่ต่อสู้</button></article><article class="activity-card"><span class="eyebrow">${p.season.id} · 4 WEEKS</span><h3>${W.rank(p.season.rating)} · ${p.season.rating}</h3><p>ลงแข่งแล้ว ${p.season.played} เกม · สูงสุด ${p.season.peak}<br>ฤดูกาลสิ้นสุด ${new Date(W.period().seasonEnd).toLocaleDateString('th-TH')} เล่นจัดอันดับอย่างน้อย 5 เกม รับรางวัลเมื่อเปลี่ยนฤดูกาล</p><button class="primary" id="ranked-play" ${!connected||!p.account?'disabled':''}>ประลองจัดอันดับ</button>${!p.account?'<button class="text-button" data-view="account">ผูกบัญชีเพื่อเล่นจัดอันดับ</button>':''}</article><article class="activity-card"><span class="eyebrow">PRIVATE ROOM</span><h3>ท้าประลองเพื่อน</h3><p>ส่งรหัสให้เพื่อนเข้าเล่น 1v1 มีอีโมตและขอแข่งใหม่ ห้องเพื่อนไม่เพิ่มรางวัลหรืออันดับ</p><button class="primary" data-host="friendly" ${!connected?'disabled':''}>สร้างห้องประลอง</button></article><article class="activity-card"><span class="eyebrow">CO-OP BOSS</span><h3>ร่วมปราบมหาภูติ</h3><p>สองคนรวมสำรับและใช้มือกับสนามร่วมกัน ผลัดกันควบคุมทีมแต่ละเทิร์น ต่อสู้บอสเงาราตรี 36 HP</p><button class="primary" data-host="coop" ${!connected?'disabled':''}>สร้างห้องร่วมมือ</button></article><article class="activity-card"><h3>เข้าห้องด้วยรหัส</h3><label>รหัสห้อง 6 ตัว<input id="room-code" maxlength="6" placeholder="A1B2C3" autocomplete="off"></label><button class="primary" id="join-room" ${!connected?'disabled':''}>เข้าร่วม →</button></article></div><div class="section-heading"><h2>อันดับฤดูกาล ${p.season.id}</h2><span>20 อันดับแรก</span></div><div class="leaderboard">${leaderboard.length?leaderboard.map((a,i)=>`<div><b>${i+1}</b><span>${esc(a.name)}<small>${a.rank} · ${a.played} เกม</small></span><strong>${a.rating}</strong></div>`).join(''):'<p class="muted">ยังไม่มีผู้เล่นจัดอันดับในฤดูกาลนี้</p>'}</div>`;}
function waitingPage(){return `<section class="queue-panel"><span class="eyebrow">${waiting.kind==='coop'?'CO-OP BOSS':'FRIENDLY DUEL'}</span><h1>รอเพื่อนร่วมวงอาคม</h1><p>ให้เพื่อนเปิดหน้าออนไลน์แล้วกรอกรหัสนี้<br>ห้องมีอายุ 10 นาที</p><div class="room-code">${waiting.code}</div><button class="secondary" id="copy-room">คัดลอกรหัส</button><button class="secondary" id="cancel-queue">ปิดห้อง</button></section>`;}
function accountPage(){return sectionTitle('KEEP YOUR JOURNEY','บัญชีและการกู้คืน','ผูกชื่อบัญชีและรหัสผ่านกับความก้าวหน้า Guest นี้ ไม่ต้องใช้อีเมล เก็บรหัสกู้คืนไว้ในที่ปลอดภัย')+(profile.account?`<article class="activity-card"><h3>ผูกบัญชีแล้ว · ${esc(profile.account)}</h3><p>เข้าสู่ระบบจากเครื่องอื่นด้วยชื่อบัญชีและรหัสผ่าน การเข้าเครื่องใหม่จะพักการเชื่อมต่อเครื่องเดิม</p><button class="secondary" id="logout-account">ออกจากบัญชี</button></article>`:'<p class="connection-warning">กำลังเล่นแบบ Guest ล้างคุกกี้แล้วจะกลับบัญชีนี้ไม่ได้หากยังไม่ผูกบัญชี การเข้าสู่บัญชีอื่นจะไม่รวมความก้าวหน้า Guest นี้</p>')+`<form id="account-form" class="account-form"><label>การจัดการ<select name="action" id="auth-action"><option value="register">ผูกบัญชีใหม่กับตัวละครนี้</option><option value="login">เข้าสู่บัญชีที่มีอยู่</option><option value="recover">ตั้งรหัสผ่านใหม่ด้วยรหัสกู้คืน</option></select></label><label>ชื่อบัญชี<input name="username" id="auth-username" minlength="4" maxlength="24" pattern="[A-Za-z0-9_]{4,24}" autocomplete="username" required placeholder="อักษรอังกฤษ ตัวเลข หรือ _"></label><label>รหัสผ่าน (หรือรหัสใหม่เมื่อกู้คืน)<input name="password" id="auth-password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required></label><label>รหัสกู้คืน · กรอกเฉพาะเมื่อกู้บัญชี<input name="recovery" id="auth-recovery" maxlength="48" autocomplete="off" spellcheck="false"></label><button class="primary" ${authBusy?'disabled':''}>${authBusy?'กำลังตรวจสอบ…':'ยืนยันการจัดการบัญชี'}</button></form>${recoveryCode?`<article class="recovery-box" role="status"><h3>เก็บรหัสกู้คืนนี้ทันที</h3><p>รหัสแสดงครั้งนี้เท่านั้น ใช้ตั้งรหัสผ่านใหม่ได้ อย่าส่งให้ผู้อื่น เมื่อกู้คืนสำเร็จรหัสเดิมจะใช้ไม่ได้</p><code>${esc(recoveryCode)}</code><button class="secondary" id="copy-recovery">คัดลอกรหัสกู้คืน</button></article>`:''}`;}
function historyPage(){return sectionTitle('YOUR DUELS','บันทึกการประลอง','20 เกมล่าสุด · ความเสียหายรวมทั้งภูติและผู้เล่น · ไม่นับการเสียชีวิตจากต้นทุนหรือความเหนื่อยล้า')+`<div class="history-list">${profile.progress.history.length?profile.progress.history.map(h=>`<article><span class="result-chip ${h.won?'won':''}">${h.won?'ชนะ':h.forfeit?'ยอมแพ้':'จบเกม'}</span><div><b>${esc(h.opponent)}</b><small>${h.mode} · ${h.turns} เทิร์น · ${new Date(h.date).toLocaleString('th-TH')}</small></div><div class="history-metrics"><span>⚔ ${h.metrics.damage||0}</span><span>♥ ${h.metrics.healing||0}</span><span>◇ ${h.metrics.blocked||0}</span></div><div><small>+${h.loot.xp} EXP · +${h.loot.coins} เหรียญ${h.ratingDelta?' · อันดับ '+(h.ratingDelta>0?'+':'')+h.ratingDelta:''}</small></div></article>`).join(''):'<div class="empty-state"><b>สมุดเล่มนี้รอเรื่องราวของคุณ</b>เริ่มบทฝึกหรือประลองเกมแรกได้เลย</div>'}</div>`;}
function shop(){return sectionTitle('LOOKS, NOT POWER','ของแต่งแห่งแสงโคม','ซื้อด้วยเหรียญจากการเล่น · เปลี่ยนรูปลักษณ์โดยค่าพลังการ์ดไม่เปลี่ยน')+`<div class="feature-grid">${W.cosmetics.map(c=>{const has=profile.cosmetics.includes(c.id),active=profile.equipped[c.type]===c.id;return `<article class="activity-card"><div class="cosmetic-preview ${c.type}" style="--cosmetic:${c.color||'#d8bd8a'}">${c.icon||'✧'}</div><h3>${c.name}</h3><p>${c.price===null?'ของรางวัลพิเศษจากความสำเร็จหรือเส้นทาง':'◉ '+c.price+' เหรียญ'}</p><button class="primary" data-feature-type="cosmetic" data-feature-id="${c.id}" ${active||!has&&(c.price===null||profile.wallet.coins<c.price)||featurePending?'disabled':''}>${active?'✓ ใช้อยู่':has?'เลือกใช้':'ซื้อและใช้'}</button></article>`;}).join('')}</div>`;}
function features(which){if(!W||!profile.progress)return '<p>กำลังโหลดความก้าวหน้า…</p>';return which==='journey'?journey():which==='ritual'?ritual():which==='progress'?progressPage():which==='online'?online():which==='account'?accountPage():which==='history'?historyPage():shop();}
function showPack(result,reveal=false){lastPack=result;packRevealed=reveal;detailId=null;const list=result.cards||[];$('card-detail').innerHTML=`<div class="pack-result"><span class="eyebrow">SPIRIT SUMMONING COMPLETE</span><h2 id="detail-title">${reveal?'สายสัมพันธ์ครั้งใหม่':'วงอาคมกำลังรวมตัว'}</h2><p>${result.guarantee?'การันตี '+result.guarantee+' · ':''}การ์ดถูกบันทึกลงคลังแล้ว ปิดหน้าต่างได้โดยไม่เสียการ์ด</p><div class="reveal-grid ${reveal?'revealed':''}">${list.map((item,i)=>reveal?`<div style="--delay:${i*.12}s">${card(C.byId[item.id])}<small>${item.duplicate?'ซ้ำเกินจำนวน → ◇ '+item.shards:'เพิ่มเข้าคลังแล้ว'}</small></div>`:'<div class="ritual-back" aria-label="การ์ดที่ยังไม่เปิด">✧</div>').join('')}</div>${!reveal?'<div class="button-row"><button class="primary" id="reveal-pack">พลิกการ์ดทั้งห้า ✦</button><button class="secondary" id="skip-pack">ข้ามแอนิเมชัน</button></div>':'<button class="primary" data-close>เก็บสายสัมพันธ์นี้ไว้</button>'}</div>`;if(!$('card-dialog').open)$('card-dialog').showModal();if(reveal)window.ThaiNativeSounds?.play('summon');}
async function accountRequest(input){
  if(authBusy)return;authBusy=true;accountSwitch=true;render();
  try{const response=await fetch('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)}),data=await response.json();if(!response.ok)throw Error(data.error||'จัดการบัญชีไม่สำเร็จ');
    const old=socket;if(old){old.onclose=null;old.close();}clearTimeout(reconnectTimer);connected=false;profile=data.profile;recoveryCode=data.recovery||null;resetDraft();room=null;queued=false;waiting=null;page='account';await connect();toast(input.action==='logout'?'ออกจากบัญชีแล้ว':'บันทึกบัญชีแล้ว เก็บรหัสกู้คืนถ้ามี');
  }catch(e){toast(e.message);}finally{input.password='';input.recovery='';authBusy=false;accountSwitch=false;render();}
}
function changeDeck(id,delta){if(savePending||room||queued)return;const c=C.byId[id];if(!c||id==='wisp')return;if(delta>0){if(draft.length>=40){toast('เด็คเต็ม 40 ใบ นำการ์ดออกก่อน');return;}if(count(draft,id)>=Math.min(limit(c),owned(c))){toast('การ์ดที่มีไม่พอ เลือกอัญเชิญหรือสร้างเพิ่ม');return;}draft.push(id);}else{const i=draft.indexOf(id);if(i>=0)draft.splice(i,1);}dirty=true;render();if($('card-dialog').open&&detailId)openDetail(detailId);}
document.addEventListener('click',event=>{
  const button=event.target.closest('button,a[data-view]');if(button?.disabled)return;
  const get=key=>event.target.closest('[data-'+key+']');
  if(get('feature-type')){tx(get('feature-type').dataset.featureType,get('feature-type').dataset.featureId||null);return;}
  if(get('pack')){tx('pack',null,{faction:get('pack').dataset.pack});return;}
  if(get('craft')){tx('craft',get('craft').dataset.craft);return;}
  if(event.target.closest('#last-pack')&&profile.lastPack){showPack(profile.lastPack,true);return;}
  if((event.target.closest('#reveal-pack')||event.target.closest('#skip-pack'))&&lastPack){showPack(lastPack,true);return;}
  if(get('challenge-mode')){if(send({type:'play',mode:get('challenge-mode').dataset.challengeMode,challenge:get('challenge-mode').dataset.challengeId,faction:get('challenge-mode').dataset.challengeFaction,loaner:loaner==='owned'?null:loaner}))featurePending=true;return;}
  if(event.target.closest('#ranked-play')){send({type:'play',mode:'pvp',ranked:true,loaner:loaner==='owned'?null:loaner});return;}
  if(get('host')){send({type:'host',kind:get('host').dataset.host,loaner:loaner==='owned'?null:loaner});return;}
  if(event.target.closest('#join-room')){send({type:'join',code:$('room-code').value,loaner:loaner==='owned'?null:loaner});return;}
  if(event.target.closest('#copy-room')){window.navigator?.clipboard?.writeText(waiting.code).then(()=>toast('คัดลอกรหัสแล้ว')).catch(()=>toast('เลือกคัดลอกรหัสห้องจากหน้าจอได้เลย'));return;}
  if(event.target.closest('#copy-recovery')){window.navigator?.clipboard?.writeText(recoveryCode).then(()=>toast('เก็บรหัสนี้ในที่ปลอดภัย')).catch(()=>toast('เลือกคัดลอกรหัสจากหน้าจอได้เลย'));return;}
  if(event.target.closest('#logout-account')){accountRequest({action:'logout'});return;}
  if(event.target.closest('#new-deck')){if(savePending)return;deckSlot='new';draftName='สำรับใหม่';dirty=true;render();return;}
  if(get('use-deck')){if(send({type:'use-deck',id:get('use-deck').dataset.useDeck})){savePending=true;render();}return;}
  if(get('emote')){send({type:'emote',id:get('emote').dataset.emote});return;}
  if(event.target.closest('#mute-emotes')){emotesMuted=!emotesMuted;try{localStorage.setItem('native-emotes-muted',emotesMuted?'yes':'no');}catch{}render();return;}
  if(get('catalog-page')){catalogPage=Math.max(0,Math.min(Math.ceil(matches().length/20)-1,Number(get('catalog-page').dataset.catalogPage)));$('catalog-results').innerHTML=grid(page==='deck');return;}
  if(get('view')){const next=get('view').dataset.view;navigate(next);if(next==='online')fetch('/api/leaderboard').then(r=>r.json()).then(list=>{leaderboard=list;if(page==='online')render();}).catch(()=>{});return;}
  if(get('inspect')){openDetail(get('inspect').dataset.inspect);return;}
  if(get('add')){changeDeck(get('add').dataset.add,1);return;}
  if(get('remove')){changeDeck(get('remove').dataset.remove,-1);return;}
  if(get('faction-library')){faction=get('faction-library').dataset.factionLibrary;search='';tier='all';cost='all';navigate('collection');return;}
  if(get('starter')&&!savePending){const id=get('starter').dataset.starter;draft=C.starter(id);draftName='สำรับ'+C.factions[id].name;dirty=true;render();toast('เปลี่ยนสำรับร่างแล้ว กดบันทึกก่อนเล่น');return;}
  if(event.target.closest('#save-deck')){try{C.validateDeck(draft);if(send({type:'save',deck:draft,name:playerName,deckName:draftName,slot:deckSlot})){savePending=true;render();}}catch(e){toast(e.message);}return;}
  if(event.target.closest('[data-clear-deck]')&&!savePending){draft=[];dirty=true;render();return;}
  if(event.target.closest('[data-reset-deck]')&&!savePending){resetDraft();render();return;}
  if(get('opponents')){opponentPicker();return;}
  if(get('solo')){if(dirty){toast('ใช้เด็คที่บันทึกไว้ การแก้ไขร่างยังไม่ได้ใช้');}if(send({type:'play',mode:'solo',loaner:loaner==='owned'?null:loaner,faction:get('solo').dataset.solo})){$('card-dialog').close();}return;}
  if(get('pvp')){if(dirty)toast('ใช้เด็คที่บันทึกไว้ การแก้ไขร่างยังไม่ได้ใช้');send({type:'play',mode:'pvp',loaner:loaner==='owned'?null:loaner});return;}
  if(event.target.closest('#cancel-queue')){send({type:'cancel'});return;}
  if(get('hand')&&room){const h=room.players[room.you].hand.find(h=>h.uid===get('hand').dataset.hand);if(!h)return;if(room.active!==room.you||room.canAct===false||room.phase==='finished'){openDetail(h.card);return;}if(pending)return;selection=selection?.uid===h.uid?null:{type:'hand',uid:h.uid};render();return;}
  if(event.target.closest('#summon-card')&&selection?.type==='hand'){action({type:'summon',hand:selection.uid});return;}
  if(get('unit')&&room){const uid=get('unit').dataset.unit,u=room.players.flatMap(p=>p.board).find(u=>u.uid===uid);if(!u)return;
    if(selection?.type==='hand'&&(room.targets[selection.uid]||[]).includes(uid)){action({type:'summon',hand:selection.uid,target:uid});return;}
    if(selection?.type==='unit'&&u.owner!==room.you){action({type:'attack',unit:selection.uid,target:uid});return;}
    if(u.owner===room.you&&u.ready&&room.canAct!==false&&!pending){selection=selection?.uid===uid?null:{type:'unit',uid};render();}else openDetail(u.card);return;
  }
  if((get('player-target')||get('hit-player'))&&selection?.type==='unit'){action({type:'attack',unit:selection.uid,target:'player'});return;}
  if(event.target.closest('#cancel-selection')){selection=null;render();return;}
  if(event.target.closest('#end-turn')){action({type:'end'});return;}
  if(event.target.closest('#concede')){$('confirm-dialog').showModal();return;}
  if(event.target.closest('#confirm-concede')){$('confirm-dialog').close();action({type:'concede'});return;}
  if(get('close-confirm')){$('confirm-dialog').close();return;}
  if(get('close')){$('card-dialog').close();return;}
  if(get('dismiss')){send({type:'dismiss'});return;}
  if(get('rematch')){if(['friendly','coop'].includes(room.mode)){send({type:'rematch'});return;}const options={type:'play',mode:room.mode,loaner:loaner==='owned'?null:loaner,faction:room.faction||'wood',ranked:!!room.rated,challenge:room.challenge?.split(':')[1]};send(options);return;}
  if(get('grave')&&room){const s=Number(get('grave').dataset.grave),list=room.players[s].grave;detailId=null;$('card-detail').innerHTML=`<h2 id="detail-title">สุสาน${s===room.you?'ฝ่ายเรา':'คู่ต่อสู้'} · ${list.length} ใบ</h2><p class="muted">ไพ่ในสุสานเป็นข้อมูลเปิดเผยของทั้งสองฝ่าย</p><div class="grave-list">${list.map(id=>card(C.byId[id])).join('')||'<p class="muted">ยังไม่มีวิญญาณในสุสาน</p>'}</div>`;$('card-dialog').showModal();return;}
  if(get('duel-help')){detailId=null;$('card-detail').innerHTML='<h2 id="detail-title">จังหวะการประลอง</h2><p>เลือกไพ่ในมือ → อัญเชิญ → รอเทิร์นถัดไป → เลือกภูติขอบเขียว → เลือกศัตรู</p><p>ทั้งสองตัวแลกความเสียหายพร้อมกัน เมื่อสนามศัตรูว่างให้แตะชื่อคู่ต่อสู้ด้านบนเพื่อโจมตีผู้เล่น</p><p>◇ โล่กัน 2 หน่วย · ❄ ตรึงหยุดโจมตี · ⊘ ผนึกหยุดความสามารถ</p>';$('card-dialog').showModal();}
});
document.addEventListener('input',e=>{if(e.target.id==='card-search'){search=e.target.value;catalogPage=0;$('catalog-results').innerHTML=grid(page==='deck');}if(e.target.id==='player-name'){playerName=e.target.value;dirty=true;}if(e.target.id==='deck-name'){draftName=e.target.value;dirty=true;}});
document.addEventListener('change',e=>{if(e.target.id==='loaner-choice'){loaner=e.target.value;return;}if(e.target.id==='deck-slot'){const d=profile.decks.find(d=>d.id===e.target.value);if(d){deckSlot=d.id;draft=d.cards.slice();draftName=d.name;dirty=true;render();}return;}if(e.target.id==='auth-action'){$('auth-password').autocomplete=e.target.value==='login'?'current-password':'new-password';return;}if(e.target.id==='faction-filter')faction=e.target.value;else if(e.target.id==='tier-filter')tier=e.target.value;else if(e.target.id==='cost-filter')cost=e.target.value;else return;catalogPage=0;$('catalog-results').innerHTML=grid(page==='deck');});
document.addEventListener('submit',e=>{if(e.target.id!=='account-form')return;e.preventDefault();accountRequest({action:$('auth-action').value,username:$('auth-username').value,password:$('auth-password').value,recovery:$('auth-recovery').value.trim()});});
$('chat-form').addEventListener('submit',e=>{e.preventDefault();const input=$('chat-input');if(input.value.trim()&&send({type:'chat',text:input.value.trim()}))input.value='';});
function chat(entry){const line=document.createElement('p'),name=document.createElement('b'),text=document.createTextNode(' '+entry.text);name.textContent=entry.name;line.append(name,text);$('chat-lines').append(line);while($('chat-lines').children.length>40)$('chat-lines').firstElementChild.remove();$('chat-lines').scrollTop=$('chat-lines').scrollHeight;}
async function connect(){
  try{const res=await fetch('/api/profile');if(!res.ok)throw Error('profile');profile=await res.json();if(!draft)resetDraft();socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/socket`);
    socket.onopen=()=>{connected=true;replaced=false;render();};
    socket.onmessage=event=>{let msg;try{msg=JSON.parse(event.data);}catch{return;}
      if(msg.type==='hello'){profile=msg.profile;if(!dirty)resetDraft();queued=msg.queued;waiting=msg.waiting||null;$('online-count').textContent=msg.online;$('chat-lines').replaceChildren();msg.chat.forEach(chat);render();}
      if(msg.type==='presence')$('online-count').textContent=msg.online;
      if(msg.type==='chat')chat(msg.entry);
      if(msg.type==='profile'){const saved=savePending;profile=msg.profile;savePending=false;featurePending=false;if(saved||!dirty)resetDraft();render();toast(msg.message);if(msg.result?.cards)showPack(msg.result);else if($('card-dialog').open&&detailId)openDetail(detailId);}
      if(msg.type==='waiting'){waiting=msg.waiting;render();}
      if(msg.type==='notice')toast(msg.message);
      if(msg.type==='emote'&&!emotesMuted)toast(msg.name+': '+msg.text);
      if(msg.type==='queue'){waiting=null;queued=msg.queued;room=null;pending=false;render();}
      if(msg.type==='room'){const previous=room;room=msg.room;waiting=null;queued=false;pending=false;selection=null;$('confirm-dialog').close();if(!previous||previous.id!==room.id){$('card-dialog').close();window.ThaiNativeSounds?.play('summon');}else if(room.phase==='finished'&&previous.phase!=='finished')window.NativeAudio?.play(room.winner===room.you?'victory':'defeat');else if(room.log.at(-1)!==previous.log.at(-1))window.NativeAudio?.play('cast');render();}
      if(msg.type==='dismissed'){room=null;selection=null;pending=false;page='home';fetch('/api/profile').then(r=>r.json()).then(p=>{profile=p;if(!dirty)resetDraft();render();}).catch(()=>{});render();}
      if(msg.type==='error'){if(msg.profile)profile=msg.profile;pending=false;savePending=false;featurePending=false;toast(msg.message);render();}
    };
    socket.onclose=e=>{connected=false;pending=false;savePending=false;featurePending=false;replaced=e.code===4001;render();if(!replaced&&!closed&&!accountSwitch)reconnectTimer=setTimeout(connect,2500);};socket.onerror=()=>{};
  }catch{connected=false;render();if(!closed)reconnectTimer=setTimeout(connect,5000);}
}
setInterval(()=>{const clock=$('turn-clock');if(clock&&room)clock.textContent=room.phase==='finished'?'—':Math.max(0,Math.ceil((room.deadline-Date.now())/1000))+'s';},500);
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(pages.includes(next)&&!room&&!queued){page=next;render();}});
window.addEventListener('pagehide',()=>{closed=true;clearTimeout(reconnectTimer);socket?.close();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
render();connect();
})();
